//! `mesh.invert_normals@1` command tests (SCAN.MESHOP.CUT.INVERT AC-1 to AC-3 through the CLI
//! and MCP surfaces, the journal and the registry definition). Expected digests come from
//! `fixtures/scan/meshop/invert_cases.txt`, written by the independent Python reference
//! `fixtures/scan/meshop/make_invert_cases.py`; nothing here was generated by running the
//! Rust code.
#![allow(clippy::unwrap_used, clippy::expect_used, clippy::panic)]

use fid_canon::{parse, CValue};
use fid_geo_cmd::{FramePrincipal, SelectionRegistry, StoredSelection};
use fid_geo_sel::{Domain, EntityId as SelEntityId, IndexSet, Selection, SelectionBody};
use fid_geo_types::{digest_mesh, FrameRef, GeometryElement, Mesh};
use fid_registry::validate::{mcp_projection, tool_name, validate_with, Limits};
use fid_registry::{Catalogue, CommandDecl, Projection};
use fid_scan_mesh_cmd::{
    command_defs, invoke_cli, invoke_mcp, InvertNormalsParams, MeshJournalEntry, MeshStore, CLI_INVERT_NORMALS,
    INVERT_NORMALS, MCP_INVERT_NORMALS,
};
use fid_types::Digest;
use fid_uuid::Uuid;

const MESH_A: &str = "018f0000-0000-7000-8000-00000000000a";
const MESH_B: &str = "018f0000-0000-7000-8000-00000000000b";
const SEL_FACE: &str = "018f0000-0000-7000-8000-0000000000f1";
const SEL_STALE: &str = "018f0000-0000-7000-8000-0000000000f2";
const SEL_OTHER: &str = "018f0000-0000-7000-8000-0000000000f3";
const NAMESPACE: &str = "6ba7b810-9dad-11d1-80b4-00c04fd430c8";

fn read(rel: &str) -> String {
    std::fs::read_to_string(format!("{}/fixtures/scan/{rel}", fid_testkit::WORKSPACE_ROOT)).unwrap()
}

fn cube() -> Mesh {
    let text = read("mesh_closed_cube.txt");
    let mut frame = None;
    let (mut v, mut t) = (Vec::new(), Vec::new());
    for line in text.lines().filter(|l| !l.starts_with('#') && !l.is_empty()) {
        let p: Vec<&str> = line.split(' ').collect();
        match p[0] {
            "frame" => {
                let mut b = [0u8; 16];
                for (i, byte) in b.iter_mut().enumerate() {
                    *byte = u8::from_str_radix(&p[1][2 * i..2 * i + 2], 16).unwrap();
                }
                frame = Some(FrameRef::from_bytes(b));
            }
            "v" => v.push([p[1].parse().unwrap(), p[2].parse().unwrap(), p[3].parse().unwrap()]),
            "t" => t.push([p[1].parse().unwrap(), p[2].parse().unwrap(), p[3].parse().unwrap()]),
            other => panic!("{other}"),
        }
    }
    Mesh::from_points(frame.unwrap(), &v, &t).unwrap()
}

fn oracle(case: &str, key: &str) -> Digest {
    let text = read("meshop/invert_cases.txt");
    let mut inside = false;
    for line in text.lines().filter(|l| !l.starts_with('#')) {
        let (k, v) = line.split_once(' ').unwrap_or((line, ""));
        if k == "case" {
            inside = v == case;
        } else if inside && k == key {
            return Digest::parse(v).unwrap();
        }
    }
    panic!("no {case}.{key}");
}

fn id(s: &str) -> Uuid {
    Uuid::parse(s).unwrap()
}

fn sel_on(target: &str, digest: fid_geo_types::ElementDigest, tris: &[u64], count: u64) -> Selection {
    let set = IndexSet::from_indices(Domain::Triangles, tris, count).unwrap();
    Selection::new(SelEntityId::from_bytes(*id(target).as_bytes()), digest, SelectionBody::IndexSet(set))
}

/// Mesh A is the closed cube, mesh B the cube with triangle 0 reversed (another element).
/// SEL_FACE selects the z = 0 face of A; SEL_STALE claims to target B but was made on A's
/// content; SEL_OTHER targets B correctly.
fn setup() -> (MeshStore, SelectionRegistry) {
    let a = cube();
    let mut tris: Vec<[u64; 3]> = a.triangles().collect();
    tris[0] = [tris[0][0], tris[0][2], tris[0][1]];
    let pts: Vec<[f64; 3]> = (0..a.vertex_count()).map(|v| a.vertex(v).unwrap()).collect();
    let b = Mesh::from_points(a.frame(), &pts, &tris).unwrap();
    let mut sels = SelectionRegistry::new();
    let face = Selection::on_element(
        SelEntityId::from_bytes(*id(MESH_A).as_bytes()),
        &GeometryElement::Mesh(a.clone()),
        Domain::Triangles,
        &[0, 1],
    )
    .unwrap();
    sels.insert(StoredSelection { id: id(SEL_FACE), selection: face });
    sels.insert(StoredSelection { id: id(SEL_STALE), selection: sel_on(MESH_B, digest_mesh(&a), &[0, 1], 12) });
    sels.insert(StoredSelection { id: id(SEL_OTHER), selection: sel_on(MESH_B, digest_mesh(&b), &[0], 12) });
    let mut store = MeshStore::new();
    store.insert_raw(id(MESH_A), a).unwrap();
    store.insert_raw(id(MESH_B), b).unwrap();
    (store, sels)
}

fn human() -> FramePrincipal {
    FramePrincipal::Human { id: "user:alice".to_owned() }
}

fn obj(bytes: &[u8]) -> std::collections::BTreeMap<String, CValue> {
    let CValue::Obj(o) = parse(bytes).unwrap() else { panic!("not an object") };
    o
}

fn s<'a>(o: &'a std::collections::BTreeMap<String, CValue>, k: &str) -> &'a str {
    match o.get(k) {
        Some(CValue::Str(v)) => v,
        other => panic!("{k}: {other:?}"),
    }
}

fn n(o: &std::collections::BTreeMap<String, CValue>, k: &str) -> f64 {
    match o.get(k) {
        Some(CValue::Num(v)) => *v,
        other => panic!("{k}: {other:?}"),
    }
}

#[test]
fn ac1_whole_mesh_through_cli_then_mcp_reproduces_the_geometry() {
    let (mut store, sels) = setup();
    let mut journal: Vec<MeshJournalEntry> = Vec::new();
    let ns = id(NAMESPACE);
    let out =
        invoke_cli(&mut store, &sels, &mut journal, &human(), ns, &[CLI_INVERT_NORMALS, "--mesh", MESH_A, "--json"])
            .unwrap();
    let r = obj(&out);
    assert_eq!(s(&r, "input_digest"), oracle("whole", "input_digest").as_str());
    assert_eq!(s(&r, "digest"), oracle("whole", "output_digest").as_str());
    assert_eq!(n(&r, "inverted_triangles"), 12.0);
    assert_eq!(n(&r, "negated_normals"), 0.0, "the cube stores no normals");
    assert_eq!(journal.len(), 1);
    assert_eq!(journal[0].command, INVERT_NORMALS);
    assert_eq!(journal[0].input, id(MESH_A));
    assert_eq!(journal[0].selection, None);
    let first = id(s(&r, "mesh"));
    assert_eq!(store.digest(&first), Some(oracle("whole", "output_digest")));

    let raw = format!(r#"{{"mesh":"{first}"}}"#);
    let out2 = invoke_mcp(&mut store, &sels, &mut journal, &human(), ns, MCP_INVERT_NORMALS, raw.as_bytes()).unwrap();
    let r2 = obj(&out2);
    assert_eq!(s(&r2, "digest"), oracle("twice", "output_digest").as_str());
    let second = id(s(&r2, "mesh"));
    assert_eq!(store.get(&second).unwrap().mesh(), store.get(&id(MESH_A)).unwrap().mesh());
    assert_eq!(journal.len(), 2);
    assert_eq!(store.len(), 4);
}

#[test]
fn ac2_face_selection_through_mcp() {
    let (mut store, sels) = setup();
    let mut journal = Vec::new();
    let raw = format!(r#"{{"mesh":"{MESH_A}","selection":"{SEL_FACE}"}}"#);
    let out = invoke_mcp(&mut store, &sels, &mut journal, &human(), id(NAMESPACE), MCP_INVERT_NORMALS, raw.as_bytes())
        .unwrap();
    let r = obj(&out);
    assert_eq!(s(&r, "digest"), oracle("face_z0", "output_digest").as_str());
    assert_eq!(n(&r, "inverted_triangles"), 2.0);
    let new = id(s(&r, "mesh"));
    assert_eq!(store.get(&new).unwrap().mesh().facts().misoriented_pairs, 4);
    let sel_digest = sels.get(&id(SEL_FACE)).unwrap().selection.content_digest().unwrap().to_digest();
    assert_eq!(journal[0].selection, Some((id(SEL_FACE), sel_digest)));
}

#[test]
fn ac3_refusals_journal_nothing_and_store_nothing() {
    let (mut store, sels) = setup();
    let mut journal = Vec::new();
    let ns = id(NAMESPACE);
    let mut run = |args: &[&str]| invoke_cli(&mut store, &sels, &mut journal, &human(), ns, args).unwrap_err().code();
    assert_eq!(run(&[CLI_INVERT_NORMALS, "--mesh", MESH_B, "--selection", SEL_STALE]), "scan.mesh.stale_selection");
    assert_eq!(run(&[CLI_INVERT_NORMALS, "--mesh", MESH_A, "--selection", SEL_OTHER]), "scan.mesh.selection_target");
    assert_eq!(run(&[CLI_INVERT_NORMALS, "--mesh", MESH_B, "--selection", SEL_FACE]), "scan.mesh.selection_target");
    let unknown = "018f0000-0000-7000-8000-0000000000ee";
    assert_eq!(run(&[CLI_INVERT_NORMALS, "--mesh", unknown]), "scan.mesh.not_found");
    assert_eq!(run(&[CLI_INVERT_NORMALS, "--mesh", MESH_A, "--selection", unknown]), "scan.mesh.selection_not_found");
    assert_eq!(run(&[CLI_INVERT_NORMALS, "--mesh", MESH_A, "--mesh", MESH_A]), "scan.mesh.bad_params");
    assert_eq!(run(&[CLI_INVERT_NORMALS, "--mesh"]), "scan.mesh.bad_params");
    assert_eq!(run(&[CLI_INVERT_NORMALS, "--mesh", "not-a-uuid"]), "scan.mesh.bad_params");
    assert_eq!(run(&[CLI_INVERT_NORMALS, "--selection", SEL_FACE]), "scan.mesh.bad_params");
    assert_eq!(run(&[CLI_INVERT_NORMALS, "--mesh", MESH_A, "--force"]), "scan.mesh.bad_params");
    assert_eq!(run(&["invert-everything", "--mesh", MESH_A]), "scan.mesh.unknown_command");
    for raw in [
        r#"{"mesh":"018f0000-0000-7000-8000-00000000000a","extra":1}"#,
        r#"{"mesh":"018f0000-0000-7000-8000-00000000000a","mesh":"018f0000-0000-7000-8000-00000000000a"}"#,
        r#"{"mesh":7}"#,
        r#"{"selection":"018f0000-0000-7000-8000-0000000000f1"}"#,
        r#"[]"#,
    ] {
        let e =
            invoke_mcp(&mut store, &sels, &mut journal, &human(), ns, MCP_INVERT_NORMALS, raw.as_bytes()).unwrap_err();
        assert_eq!(e.code(), "scan.mesh.bad_params", "{raw}");
    }
    let e = invoke_mcp(&mut store, &sels, &mut journal, &human(), ns, "mesh_flip", b"{}").unwrap_err();
    assert_eq!(e.code(), "scan.mesh.unknown_command");
    assert!(journal.is_empty());
    assert_eq!(store.len(), 2);

    // The same command on the same input derives the same ID: the second run is refused.
    let p = InvertNormalsParams { mesh: id(MESH_A), selection: None };
    fid_scan_mesh_cmd::invert_normals(&mut store, &sels, &mut journal, &human(), ns, &p).unwrap();
    let e = fid_scan_mesh_cmd::invert_normals(&mut store, &sels, &mut journal, &human(), ns, &p).unwrap_err();
    assert_eq!(e.code(), "scan.mesh.id_collision");
    assert_eq!(journal.len(), 1);
    assert_eq!(store.len(), 3);
}

#[test]
fn cli_and_mcp_give_the_same_bytes_and_journal_and_agents_record_their_branch() {
    let ns = id(NAMESPACE);
    let agent = FramePrincipal::Agent { id: "agent:a1".to_owned(), branch: "agent/a1".to_owned() };
    let (mut s1, sels1) = setup();
    let (mut s2, sels2) = setup();
    let (mut j1, mut j2) = (Vec::new(), Vec::new());
    let a = invoke_cli(
        &mut s1,
        &sels1,
        &mut j1,
        &agent,
        ns,
        &[CLI_INVERT_NORMALS, "--selection", SEL_FACE, "--mesh", MESH_A],
    )
    .unwrap();
    let raw = format!(r#"{{"selection":"{SEL_FACE}","mesh":"{MESH_A}"}}"#);
    let b = invoke_mcp(&mut s2, &sels2, &mut j2, &agent, ns, MCP_INVERT_NORMALS, raw.as_bytes()).unwrap();
    assert_eq!(a, b);
    assert_eq!(j1, j2);
    assert_eq!(j1[0].to_canonical_bytes().unwrap(), j2[0].to_canonical_bytes().unwrap());
    assert_eq!(j1[0].branch.as_deref(), Some("agent/a1"));
    assert_eq!(j1[0].principal, "agent:a1");
}

#[test]
fn the_registry_definition_validates_and_is_exposed() {
    let defs = command_defs().unwrap();
    assert_eq!(defs.len(), 1);
    let d = &defs[0];
    assert_eq!(format!("{}@{}", d.id, d.major), INVERT_NORMALS);
    assert_eq!(d.side_effect.as_str(), "W2");
    assert_eq!(d.determinism.as_str(), "D0");
    assert_eq!(tool_name(&d.id, d.major), MCP_INVERT_NORMALS);
    assert_eq!(mcp_projection(d), Projection::Exposed);
    let catalogue = Catalogue::geo_frame().unwrap();
    let errs = validate_with(&[CommandDecl(d.to_value())], &Limits::default(), &catalogue);
    assert!(errs.is_empty(), "{errs:?}");
}
